using Microsoft.AspNetCore.Mvc;
namespace TaskPanel.Api;
[ApiController,Route("api/auth")]public class AuthController(AuthService s):ControllerBase{[HttpPost("login")]public async Task<IActionResult>Login(LoginRequest r){var x=await s.Login(r);return x is null?Unauthorized():Ok(x);}}
[ApiController,Route("api/tasks")]public class TasksController(TaskService s):ControllerBase{CurrentUser Me=>(CurrentUser)HttpContext.Items["User"]!;[HttpGet]public async Task<IActionResult>Get()=>Ok(await s.Get(Me));[HttpPost]public async Task<IActionResult>Create(CreateTaskRequest r){try{var id=await s.Create(r,Me);return Created($"/api/tasks/{id}",new{id});}catch(UnauthorizedAccessException){return Forbid();}}[HttpPatch("{id:long}/status")]public async Task<IActionResult>Status(long id,StatusRequest r)=>await s.Status(id,r.Status,Me)?NoContent():NotFound();}
[ApiController,Route("api/users")]public class UsersController(UserService s):ControllerBase{CurrentUser Me=>(CurrentUser)HttpContext.Items["User"]!;[HttpGet("me")]public IActionResult MeRoute()=>Ok(Me);[HttpGet]public async Task<IActionResult>Get()=>Me.Role=="admin"?Ok(await s.Get()):Forbid();[HttpPost]public async Task<IActionResult>Create(CreateUserRequest r){try{return await s.Create(r,Me)?StatusCode(201):BadRequest();}catch(UnauthorizedAccessException){return Forbid();}}}
